mapper.select:

SELECT DATE(wo.plan_end_time) AS date, COUNT(*) AS planned FROM pro_work_order wo
WHERE wo.status NOT IN ('0','6') AND wo.plan_end_time >= #{start} AND wo.plan_end_time < #{end}

GROUP BY DATE(wo.plan_end_time) ORDER BY date


SELECT DATE(wo.actual_end_time) AS date, COUNT(*) AS completed FROM pro_work_order wo
WHERE wo.status IN ('2','3') AND wo.actual_end_time >= #{start} AND wo.actual_end_time <= #{now}

GROUP BY DATE(wo.actual_end_time) ORDER BY date
